import { sql } from 'drizzle-orm';
import {
  type AnyPgColumn,
  bigint,
  bigserial,
  boolean,
  index,
  integer,
  jsonb,
  pgTable,
  primaryKey,
  smallint,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';

// Conventions (see docs/DATABASE.md):
// - UUIDv7 primary keys generated by the application (sortable, node-independent).
// - Every tenant-owned table carries tenant_id; every query filters by it.
// - Mutable rows carry `version` for optimistic locking and sync conflict detection.
// - All timestamps are timestamptz in UTC.
// - is_test marks synthetic/demo rows so they can be purged without touching real data.

const ts = (name: string) => timestamp(name, { withTimezone: true, mode: 'date' });

export const tenants = pgTable('tenants', {
  id: uuid('id').primaryKey(),
  code: text('code').notNull().unique(),
  name: text('name').notNull(),
  brand: text('brand'),
  isTest: boolean('is_test').notNull().default(false),
  createdAt: ts('created_at').notNull().defaultNow(),
});

export const users = pgTable(
  'users',
  {
    id: uuid('id').primaryKey(),
    tenantId: uuid('tenant_id')
      .notNull()
      .references(() => tenants.id),
    username: text('username').notNull(),
    email: text('email'),
    activatedAt: ts('activated_at'),
    encryptedTotpSecret: text('encrypted_totp_secret'),
    totpLastStep: integer('totp_last_step').notNull().default(-1),
    displayName: text('display_name').notNull(),
    passwordHash: text('password_hash').notNull(),
    roles: text('roles').array().notNull(),
    isActive: boolean('is_active').notNull().default(true),
    isTest: boolean('is_test').notNull().default(false),
    failedLoginCount: integer('failed_login_count').notNull().default(0),
    lockedUntil: ts('locked_until'),
    lastLoginAt: ts('last_login_at'),
    createdAt: ts('created_at').notNull().defaultNow(),
    updatedAt: ts('updated_at').notNull().defaultNow(),
    version: integer('version').notNull().default(1),
  },
  (t) => [uniqueIndex('users_tenant_username_uq').on(t.tenantId, t.username), uniqueIndex('users_email_uq').on(t.email)],
);

export const sessions = pgTable(
  'sessions',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id),
    tenantId: uuid('tenant_id')
      .notNull()
      .references(() => tenants.id),
    tokenHash: text('token_hash').notNull().unique(),
    verifiedWithTotp: boolean('verified_with_totp').notNull().default(false),
    createdAt: ts('created_at').notNull().defaultNow(),
    expiresAt: ts('expires_at').notNull(),
    lastSeenAt: ts('last_seen_at').notNull().defaultNow(),
    revokedAt: ts('revoked_at'),
    ip: text('ip'),
    userAgent: text('user_agent'),
  },
  (t) => [index('sessions_user_idx').on(t.userId)],
);

// Codes and invitation/reset tokens are stored only as keyed hashes.
export const authChallenges = pgTable('auth_challenges', {
  id: uuid('id').primaryKey(),
  tenantId: uuid('tenant_id').notNull().references(() => tenants.id),
  userId: uuid('user_id').notNull().references(() => users.id),
  purpose: text('purpose').notNull(),
  secretHash: text('secret_hash').notNull(),
  proofHash: text('proof_hash'),
  passwordHash: text('password_hash'),
  encryptedTotpSecret: text('encrypted_totp_secret'),
  attempts: integer('attempts').notNull().default(0),
  expiresAt: ts('expires_at').notNull(),
  consumedAt: ts('consumed_at'),
  invitationDelivery: text('invitation_delivery').notNull().default('manual'),
  invitationSentAt: ts('invitation_sent_at'),
  // Category of the last failed email delivery (see MAIL_FAILURES); never the raw SMTP error.
  invitationFailure: text('invitation_failure'),
  createdAt: ts('created_at').notNull().defaultNow(),
}, (t) => [index('auth_challenges_user_idx').on(t.userId, t.purpose)]);

export const departments = pgTable(
  'departments',
  {
    id: uuid('id').primaryKey(),
    tenantId: uuid('tenant_id')
      .notNull()
      .references(() => tenants.id),
    code: text('code').notNull(),
    name: text('name').notNull(),
    sortOrder: smallint('sort_order').notNull().default(0),
    isActive: boolean('is_active').notNull().default(true),
    createdAt: ts('created_at').notNull().defaultNow(),
    updatedAt: ts('updated_at').notNull().defaultNow(),
    version: integer('version').notNull().default(1),
  },
  (t) => [uniqueIndex('departments_tenant_code_uq').on(t.tenantId, t.code)],
);

export const customers = pgTable(
  'customers',
  {
    id: uuid('id').primaryKey(),
    tenantId: uuid('tenant_id')
      .notNull()
      .references(() => tenants.id),
    fullName: text('full_name'),
    phone: text('phone'),
    isTest: boolean('is_test').notNull().default(false),
    createdAt: ts('created_at').notNull().defaultNow(),
    updatedAt: ts('updated_at').notNull().defaultNow(),
    version: integer('version').notNull().default(1),
  },
  (t) => [index('customers_tenant_phone_idx').on(t.tenantId, t.phone)],
);

export const vehicles = pgTable(
  'vehicles',
  {
    id: uuid('id').primaryKey(),
    tenantId: uuid('tenant_id')
      .notNull()
      .references(() => tenants.id),
    brand: text('brand'),
    model: text('model'),
    trim: text('trim'),
    modelYear: smallint('model_year'),
    plate: text('plate'),
    vin: text('vin'),
    color: text('color'),
    isTest: boolean('is_test').notNull().default(false),
    createdAt: ts('created_at').notNull().defaultNow(),
    updatedAt: ts('updated_at').notNull().defaultNow(),
    version: integer('version').notNull().default(1),
  },
  (t) => [
    uniqueIndex('vehicles_tenant_vin_uq')
      .on(t.tenantId, t.vin)
      .where(sql`${t.vin} is not null`),
    index('vehicles_tenant_plate_idx').on(t.tenantId, t.plate),
  ],
);

export const caseCounters = pgTable(
  'case_counters',
  {
    tenantId: uuid('tenant_id')
      .notNull()
      .references(() => tenants.id),
    year: smallint('year').notNull(),
    lastValue: integer('last_value').notNull(),
  },
  (t) => [primaryKey({ columns: [t.tenantId, t.year] })],
);

export const cases = pgTable(
  'cases',
  {
    id: uuid('id').primaryKey(),
    tenantId: uuid('tenant_id')
      .notNull()
      .references(() => tenants.id),
    caseNumber: text('case_number').notNull(),
    module: text('module').notNull().default('accident'),
    vehicleId: uuid('vehicle_id')
      .notNull()
      .references(() => vehicles.id),
    customerId: uuid('customer_id').references(() => customers.id),
    // Real admission time at the workshop (may predate creation in Manage).
    admittedAt: ts('admitted_at').notNull(),
    odometerKm: integer('odometer_km'),
    damageDescription: text('damage_description'),
    vehicleLocation: text('vehicle_location'),
    coverageType: text('coverage_type').notNull().default('unknown'),
    goldenCardFileNo: text('golden_card_file_no'),
    insurerName: text('insurer_name'),
    insuranceClaimNo: text('insurance_claim_no'),
    coverageNotes: text('coverage_notes'),
    responsibleUserId: uuid('responsible_user_id').references(() => users.id),
    stage: text('stage').notNull().default('reception'),
    status: text('status').notNull().default('open'),
    // Three independent times: official commitment, internal forecast, actual.
    officialDeadlineAt: ts('official_deadline_at'),
    forecastDeliveryAt: ts('forecast_delivery_at'),
    actualDeliveryAt: ts('actual_delivery_at'),
    technicalClosedAt: ts('technical_closed_at'),
    financialClosedAt: ts('financial_closed_at'),
    // Completion (issue #12): technical and financial close are independent gates;
    // the handover needs both. The values at the financial close detect later changes.
    technicalClosedBy: uuid('technical_closed_by').references(() => users.id),
    technicalCloseNote: text('technical_close_note'),
    financialClosedBy: uuid('financial_closed_by').references(() => users.id),
    financialCloseNote: text('financial_close_note'),
    financialCloseEstimateRial: bigint('financial_close_estimate_rial', { mode: 'number' }),
    financialCloseShareRial: bigint('financial_close_share_rial', { mode: 'number' }),
    financialCloseWaivedRial: bigint('financial_close_waived_rial', { mode: 'number' }),
    deliveredBy: uuid('delivered_by').references(() => users.id),
    recipientName: text('recipient_name'),
    recipientRelation: text('recipient_relation'),
    deliveryNote: text('delivery_note'),
    isLegacyEntry: boolean('is_legacy_entry').notNull().default(false),
    missingFields: text('missing_fields').array().notNull().default(sql`'{}'::text[]`),
    searchText: text('search_text').notNull().default(''),
    isTest: boolean('is_test').notNull().default(false),
    createdAt: ts('created_at').notNull().defaultNow(),
    createdBy: uuid('created_by')
      .notNull()
      .references(() => users.id),
    updatedAt: ts('updated_at').notNull().defaultNow(),
    updatedBy: uuid('updated_by')
      .notNull()
      .references(() => users.id),
    version: integer('version').notNull().default(1),
  },
  (t) => [
    uniqueIndex('cases_tenant_number_uq').on(t.tenantId, t.caseNumber),
    index('cases_tenant_status_stage_idx').on(t.tenantId, t.status, t.stage),
    index('cases_vehicle_idx').on(t.vehicleId),
  ],
);

export const tasks = pgTable(
  'tasks',
  {
    id: uuid('id').primaryKey(),
    tenantId: uuid('tenant_id')
      .notNull()
      .references(() => tenants.id),
    caseId: uuid('case_id')
      .notNull()
      .references(() => cases.id),
    departmentId: uuid('department_id')
      .notNull()
      .references(() => departments.id),
    title: text('title'),
    // Technicians have no accounts in phase 1; the supervisor records on their behalf.
    technicianName: text('technician_name'),
    technicianCode: text('technician_code'),
    status: text('status').notNull().default('pending'),
    plannedStartAt: ts('planned_start_at'),
    plannedEndAt: ts('planned_end_at'),
    actualStartAt: ts('actual_start_at'),
    actualEndAt: ts('actual_end_at'),
    completedBy: uuid('completed_by').references(() => users.id),
    approvedAt: ts('approved_at'),
    approvedBy: uuid('approved_by').references(() => users.id),
    weight: smallint('weight').notNull().default(1),
    sortOrder: integer('sort_order').notNull().default(0),
    notes: text('notes'),
    // Corrective activity opened by a failed QC item.
    qcInspectionId: uuid('qc_inspection_id').references((): AnyPgColumn => qcInspections.id),
    isTest: boolean('is_test').notNull().default(false),
    createdAt: ts('created_at').notNull().defaultNow(),
    createdBy: uuid('created_by')
      .notNull()
      .references(() => users.id),
    updatedAt: ts('updated_at').notNull().defaultNow(),
    version: integer('version').notNull().default(1),
  },
  (t) => [index('tasks_case_idx').on(t.caseId), index('tasks_tenant_status_idx').on(t.tenantId, t.status)],
);

export const taskDependencies = pgTable(
  'task_dependencies',
  {
    taskId: uuid('task_id')
      .notNull()
      .references(() => tasks.id),
    dependsOnTaskId: uuid('depends_on_task_id')
      .notNull()
      .references(() => tasks.id),
  },
  (t) => [primaryKey({ columns: [t.taskId, t.dependsOnTaskId] })],
);

export const blockers = pgTable(
  'blockers',
  {
    id: uuid('id').primaryKey(),
    tenantId: uuid('tenant_id')
      .notNull()
      .references(() => tenants.id),
    caseId: uuid('case_id')
      .notNull()
      .references(() => cases.id),
    taskId: uuid('task_id').references(() => tasks.id),
    reason: text('reason').notNull(),
    description: text('description'),
    // occurred_at: when the problem started; recorded_at: when it entered Manage.
    // The gap between them separates late reporting from the blocker itself.
    occurredAt: ts('occurred_at').notNull(),
    recordedAt: ts('recorded_at').notNull().defaultNow(),
    recordedBy: uuid('recorded_by')
      .notNull()
      .references(() => users.id),
    lastFollowUpAt: ts('last_follow_up_at'),
    followUpCount: integer('follow_up_count').notNull().default(0),
    resolvedAt: ts('resolved_at'),
    resolvedBy: uuid('resolved_by').references(() => users.id),
    resolutionNote: text('resolution_note'),
    // "Part not arrived" blockers may name the part; its handover resolves them.
    partRequestId: uuid('part_request_id').references((): AnyPgColumn => partRequests.id),
    isTest: boolean('is_test').notNull().default(false),
    updatedAt: ts('updated_at').notNull().defaultNow(),
    version: integer('version').notNull().default(1),
  },
  (t) => [index('blockers_case_idx').on(t.caseId), index('blockers_tenant_open_idx').on(t.tenantId, t.resolvedAt)],
);

// One row per assessment version of a case: version 1 is the initial
// assessment, later versions are supplements (hidden damage). Items of a final
// version never change; a supplement copies them and the previous version is
// marked superseded when the supplement is finalized.
export const assessments = pgTable(
  'assessments',
  {
    id: uuid('id').primaryKey(),
    tenantId: uuid('tenant_id')
      .notNull()
      .references(() => tenants.id),
    caseId: uuid('case_id')
      .notNull()
      .references(() => cases.id),
    versionNo: smallint('version_no').notNull(),
    kind: text('kind').notNull(),
    status: text('status').notNull().default('draft'),
    previousId: uuid('previous_id'),
    assessorName: text('assessor_name').notNull(),
    assessorOrg: text('assessor_org'),
    assessedAt: ts('assessed_at').notNull(),
    reason: text('reason'),
    discoveredAt: ts('discovered_at'),
    notes: text('notes'),
    finalizedAt: ts('finalized_at'),
    finalizedBy: uuid('finalized_by').references(() => users.id),
    // Totals are frozen at finalization so later price lists cannot alter them.
    partsRial: bigint('parts_rial', { mode: 'number' }).notNull().default(0),
    labourRial: bigint('labour_rial', { mode: 'number' }).notNull().default(0),
    approvedRial: bigint('approved_rial', { mode: 'number' }),
    authorizationStatus: text('authorization_status').notNull().default('pending'),
    authorizationSource: text('authorization_source'),
    authorizationMethod: text('authorization_method'),
    authorizationRef: text('authorization_ref'),
    authorizationAt: ts('authorization_at'),
    authorizationNote: text('authorization_note'),
    authorizationRecordedBy: uuid('authorization_recorded_by').references(() => users.id),
    blockerId: uuid('blocker_id').references(() => blockers.id),
    isTest: boolean('is_test').notNull().default(false),
    createdAt: ts('created_at').notNull().defaultNow(),
    createdBy: uuid('created_by')
      .notNull()
      .references(() => users.id),
    updatedAt: ts('updated_at').notNull().defaultNow(),
    version: integer('version').notNull().default(1),
  },
  (t) => [
    uniqueIndex('assessments_case_version_uq').on(t.caseId, t.versionNo),
    // At most one draft per case.
    uniqueIndex('assessments_case_draft_uq')
      .on(t.caseId)
      .where(sql`${t.status} = 'draft'`),
    index('assessments_tenant_auth_idx').on(t.tenantId, t.authorizationStatus),
  ],
);

export const assessmentItems = pgTable(
  'assessment_items',
  {
    id: uuid('id').primaryKey(),
    tenantId: uuid('tenant_id')
      .notNull()
      .references(() => tenants.id),
    assessmentId: uuid('assessment_id')
      .notNull()
      .references(() => assessments.id),
    lineNo: smallint('line_no').notNull(),
    action: text('action').notNull(),
    description: text('description').notNull(),
    partNumber: text('part_number'),
    quantity: smallint('quantity').notNull().default(1),
    unitPriceRial: bigint('unit_price_rial', { mode: 'number' }).notNull().default(0),
    labourDepartmentId: uuid('labour_department_id').references(() => departments.id),
    labourRial: bigint('labour_rial', { mode: 'number' }).notNull().default(0),
    evidence: text('evidence'),
    approvalStatus: text('approval_status').notNull().default('pending'),
    originItemId: uuid('origin_item_id'),
    // Copied lines start unchanged; any edit in the supplement sets this.
    changed: boolean('changed').notNull().default(true),
    isTest: boolean('is_test').notNull().default(false),
    createdAt: ts('created_at').notNull().defaultNow(),
    updatedAt: ts('updated_at').notNull().defaultNow(),
  },
  (t) => [index('assessment_items_assessment_idx').on(t.assessmentId, t.lineNo)],
);

// One row per needed part of a case. Each step keeps its own time so delays
// can be attributed: need → stock check / reservation → order (ETA) → receipt
// with inspection → handover to the repair unit.
export const partRequests = pgTable(
  'part_requests',
  {
    id: uuid('id').primaryKey(),
    tenantId: uuid('tenant_id')
      .notNull()
      .references(() => tenants.id),
    caseId: uuid('case_id')
      .notNull()
      .references(() => cases.id),
    // Root assessment line (first version) this need comes from, if any.
    assessmentItemId: uuid('assessment_item_id').references(() => assessmentItems.id),
    description: text('description').notNull(),
    partNumber: text('part_number'),
    quantity: smallint('quantity').notNull().default(1),
    source: text('source').notNull(),
    status: text('status').notNull().default('needed'),
    inStock: boolean('in_stock'),
    stockCheckedAt: ts('stock_checked_at'),
    reservedAt: ts('reserved_at'),
    approvedUnitPriceRial: bigint('approved_unit_price_rial', { mode: 'number' }),
    unitPriceRial: bigint('unit_price_rial', { mode: 'number' }),
    priceApprovalRef: text('price_approval_ref'),
    priceApprovedBy: text('price_approved_by'),
    supplier: text('supplier'),
    orderRef: text('order_ref'),
    orderedAt: ts('ordered_at'),
    etaAt: ts('eta_at'),
    firstEtaAt: ts('first_eta_at'),
    receivedAt: ts('received_at'),
    receiptDocNo: text('receipt_doc_no'),
    inspection: text('inspection'),
    inspectionNote: text('inspection_note'),
    handedOverAt: ts('handed_over_at'),
    handedOverDepartmentId: uuid('handed_over_department_id').references(() => departments.id),
    recipientName: text('recipient_name'),
    cancelledAt: ts('cancelled_at'),
    cancelReason: text('cancel_reason'),
    financeBasis: text('finance_basis'),
    financeExceptionId: uuid('finance_exception_id'),
    notes: text('notes'),
    isTest: boolean('is_test').notNull().default(false),
    createdAt: ts('created_at').notNull().defaultNow(),
    createdBy: uuid('created_by')
      .notNull()
      .references(() => users.id),
    updatedAt: ts('updated_at').notNull().defaultNow(),
    version: integer('version').notNull().default(1),
  },
  (t) => [
    index('part_requests_case_idx').on(t.caseId),
    index('part_requests_tenant_status_idx').on(t.tenantId, t.status),
  ],
);

// Payer split of a case's estimate (one row per case, created on first edit).
export const caseFinance = pgTable('case_finance', {
  caseId: uuid('case_id')
    .primaryKey()
    .references(() => cases.id),
  tenantId: uuid('tenant_id')
    .notNull()
    .references(() => tenants.id),
  customerShareRial: bigint('customer_share_rial', { mode: 'number' }),
  insurerShareRial: bigint('insurer_share_rial', { mode: 'number' }),
  companyShareRial: bigint('company_share_rial', { mode: 'number' }),
  note: text('note'),
  isTest: boolean('is_test').notNull().default(false),
  updatedAt: ts('updated_at').notNull().defaultNow(),
  updatedBy: uuid('updated_by')
    .notNull()
    .references(() => users.id),
  version: integer('version').notNull().default(1),
});

// Advance payments and spending exceptions. Proposer, approver and payment
// confirmer are recorded separately; the approver is never the proposer.
export const financialApprovals = pgTable(
  'financial_approvals',
  {
    id: uuid('id').primaryKey(),
    tenantId: uuid('tenant_id')
      .notNull()
      .references(() => tenants.id),
    caseId: uuid('case_id')
      .notNull()
      .references(() => cases.id),
    kind: text('kind').notNull(),
    status: text('status').notNull().default('proposed'),
    amountRial: bigint('amount_rial', { mode: 'number' }).notNull(),
    coversEstimateRial: bigint('covers_estimate_rial', { mode: 'number' }).notNull(),
    reason: text('reason').notNull(),
    proposedAt: ts('proposed_at').notNull().defaultNow(),
    proposedBy: uuid('proposed_by')
      .notNull()
      .references(() => users.id),
    decidedAt: ts('decided_at'),
    decidedBy: uuid('decided_by').references(() => users.id),
    decisionNote: text('decision_note'),
    paidAt: ts('paid_at'),
    paymentRef: text('payment_ref'),
    paymentConfirmedBy: uuid('payment_confirmed_by').references(() => users.id),
    isTest: boolean('is_test').notNull().default(false),
    updatedAt: ts('updated_at').notNull().defaultNow(),
    version: integer('version').notNull().default(1),
  },
  (t) => [
    index('financial_approvals_case_idx').on(t.caseId),
    index('financial_approvals_tenant_status_idx').on(t.tenantId, t.status),
  ],
);

// Settlement payments of the customer share recorded by the cashier (advances
// are confirmed on financial_approvals). Append-only by the application.
export const casePayments = pgTable(
  'case_payments',
  {
    id: uuid('id').primaryKey(),
    tenantId: uuid('tenant_id')
      .notNull()
      .references(() => tenants.id),
    caseId: uuid('case_id')
      .notNull()
      .references(() => cases.id),
    amountRial: bigint('amount_rial', { mode: 'number' }).notNull(),
    paymentRef: text('payment_ref').notNull(),
    paidAt: ts('paid_at').notNull(),
    note: text('note'),
    recordedBy: uuid('recorded_by')
      .notNull()
      .references(() => users.id),
    isTest: boolean('is_test').notNull().default(false),
    createdAt: ts('created_at').notNull().defaultNow(),
  },
  (t) => [index('case_payments_case_idx').on(t.caseId)],
);

// One row per QC round; immutable once recorded. `checks` holds the result of
// every checklist item (see QC_CHECK_ITEMS) and the corrective task it opened.
export const qcInspections = pgTable(
  'qc_inspections',
  {
    id: uuid('id').primaryKey(),
    tenantId: uuid('tenant_id')
      .notNull()
      .references(() => tenants.id),
    caseId: uuid('case_id')
      .notNull()
      .references(() => cases.id),
    round: smallint('round').notNull(),
    outcome: text('outcome').notNull(),
    checks: jsonb('checks').notNull(),
    note: text('note'),
    inspectedAt: ts('inspected_at').notNull(),
    inspectedBy: uuid('inspected_by')
      .notNull()
      .references(() => users.id),
    isTest: boolean('is_test').notNull().default(false),
    createdAt: ts('created_at').notNull().defaultNow(),
  },
  (t) => [uniqueIndex('qc_inspections_case_round_uq').on(t.caseId, t.round)],
);

// Append-only. A database trigger rejects UPDATE and DELETE (see migration
// 0001); only synthetic rows can be purged, and only by the demo reset script.
export const auditEvents = pgTable(
  'audit_events',
  {
    id: uuid('id').primaryKey(),
    tenantId: uuid('tenant_id')
      .notNull()
      .references(() => tenants.id),
    caseId: uuid('case_id'),
    entityType: text('entity_type').notNull(),
    entityId: uuid('entity_id').notNull(),
    action: text('action').notNull(),
    actorUserId: uuid('actor_user_id'),
    occurredAt: ts('occurred_at').notNull().defaultNow(),
    reason: text('reason'),
    before: jsonb('before'),
    after: jsonb('after'),
    requestId: text('request_id'),
    ip: text('ip'),
    isTest: boolean('is_test').notNull().default(false),
  },
  (t) => [
    index('audit_case_idx').on(t.caseId, t.occurredAt),
    index('audit_entity_idx').on(t.entityType, t.entityId),
  ],
);

// Outbox of entity changes, written in the same transaction as the change.
// Foundation for LAN <-> cloud sync (see docs/OFFLINE_SYNC.md).
export const changeLog = pgTable(
  'change_log',
  {
    seq: bigserial('seq', { mode: 'number' }).primaryKey(),
    id: uuid('id').notNull().unique(),
    tenantId: uuid('tenant_id').notNull(),
    nodeId: text('node_id').notNull(),
    entityType: text('entity_type').notNull(),
    entityId: uuid('entity_id').notNull(),
    op: text('op').notNull(),
    entityVersion: integer('entity_version').notNull(),
    payload: jsonb('payload').notNull(),
    isTest: boolean('is_test').notNull().default(false),
    createdAt: ts('created_at').notNull().defaultNow(),
    syncedAt: ts('synced_at'),
  },
  (t) => [index('change_log_tenant_seq_idx').on(t.tenantId, t.seq)],
);

export const idempotencyKeys = pgTable(
  'idempotency_keys',
  {
    tenantId: uuid('tenant_id').notNull(),
    userId: uuid('user_id').notNull(),
    key: text('key').notNull(),
    method: text('method').notNull(),
    path: text('path').notNull(),
    responseStatus: integer('response_status').notNull(),
    responseBody: jsonb('response_body'),
    createdAt: ts('created_at').notNull().defaultNow(),
  },
  (t) => [primaryKey({ columns: [t.tenantId, t.userId, t.key] })],
);
